import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());long[] count = new long[100001];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {int val = Integer.parseInt(st.nextToken());count[val] += val;}long[] dp = new long[100001];dp[0] = 0;dp[1] = count[1];for (int i = 2; i <= 100000; i++) {dp[i] = Math.max(dp[i - 1], dp[i - 2] + count[i]);}System.out.println(dp[100000]);}}